import os, re

d = os.environ['RLM_SESSION_DIR']
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Keys:", sorted(G.keys()))

# Create correct output
test_input = G['Test input']
h, w = len(test_input), len(test_input[0])
output = [[6]*w for _ in range(h)]

def find_connected_regions(grid):
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    regions = {}

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if not visited[r][c] and grid[r][c] != 6:
                color = grid[r][c]
                region = []
                stack = [(r,c)]
                while stack:
                    rr, cc = stack.pop()
                    if visited[rr][cc]: continue
                    visited[rr][cc] = True
                    region.append((rr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nnr, nnc = rr+dr, cc+dc
                        if 0 <= nnr < len(grid) and 0 <= nnc < len(grid[0]) and not visited[nnr][nnc]:
                            if grid[nnr][nnc] == color:
                                stack.append((nnr, nnc))

                if len(region) >= 2:
                    min_r, max_r = min(x[0] for x in region), max(x[0] for x in region)
                    min_c, max_c = min(x[1] for x in region), max(x[1] for x in region)
                    regions[color] = ((min_r, max_r, min_c, max_c), len(region), region)

    return regions

regions = find_connected_regions(test_input)
sorted_colors = sorted(regions.keys(), key=lambda c: -regions[c][1])
top_colors = sorted_colors[:2]

print("Top 2 colors:", top_colors)
for color in top_colors:
    bbox, size, coords = regions[color]
    r1, r2, c1, c2 = bbox
    print(f"Color {color}: fill rows {r1}-{r2}, cols {c1}-{c2}")

for color in top_colors:
    bbox, size, coords = regions[color]
    r1, r2, c1, c2 = bbox
    for r in range(r1, r2+1):
        for c in range(c1, c2+1):
            output[r][c] = color

import json
print(json.dumps(output))
